const byId = Object.fromEntries(algorithms.map(a => [a.id, a]));
const categoryIcon = { Pathfinding:'⌘', Sorting:'≋', Searching:'⌕', Graph:'◇', 'Dynamic Programming':'▦', Greedy:'◔' };
const state = { algorithm: byId.bfs, frames: [], index: 0, playing: false, timer: null, speed: 520, grid: null, values: [], target: null };
const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
const clone = value => JSON.parse(JSON.stringify(value));
const range = (start,end) => end === undefined ? [...Array(start).keys()] : [...Array(Math.max(0,end-start)).keys()].map(i=>i+start);
const randomInt = (min,max) => Math.floor(Math.random()*(max-min+1))+min;
const shuffle = a => { const b=[...a]; for(let i=b.length-1;i>0;i--){const j=randomInt(0,i);[b[i],b[j]]=[b[j],b[i]];} return b; };
const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));

function buildNav() {
  const nav = $('#algorithm-nav'); nav.innerHTML = '';
  [...new Set(algorithms.map(a => a.category))].forEach(category => {
    const wrap = document.createElement('div'); wrap.className = 'nav-group';
    wrap.innerHTML = `<div class="nav-group-title"><span>${categoryIcon[category]}</span>${category}</div>`;
    algorithms.filter(a => a.category === category).forEach(a => {
      const button = document.createElement('button');
      button.className = `algorithm-link ${a.id === state.algorithm.id ? 'active' : ''}`;
      button.dataset.algorithm = a.id; button.innerHTML = `<span>${a.name}</span>`;
      button.addEventListener('click', () => selectAlgorithm(a.id)); wrap.appendChild(button);
    }); nav.appendChild(wrap);
  });
}

function randomGrid() {
  const rows=10, cols=18, start=37, goal=142, walls=[];
  const guaranteed = new Set();
  for(let c=1;c<=16;c++) guaranteed.add(2*cols+c);
  for(let r=2;r<=7;r++) guaranteed.add(r*cols+16);
  range(rows*cols).forEach(i => { if(i!==start&&i!==goal&&!guaranteed.has(i)&&Math.random()<.19) walls.push(i); });
  const weights = range(rows*cols).map(() => randomInt(1,5));
  return {rows,cols,start,goal,walls,weights};
}
function neighbors(index,g){ const r=Math.floor(index/g.cols),c=index%g.cols; return [[r-1,c],[r,c+1],[r+1,c],[r,c-1]].filter(([y,x])=>y>=0&&x>=0&&y<g.rows&&x<g.cols).map(([y,x])=>y*g.cols+x).filter(i=>!g.walls.includes(i)); }
function heuristic(a,b,g){ return Math.abs(Math.floor(a/g.cols)-Math.floor(b/g.cols))+Math.abs(a%g.cols-b%g.cols); }
function pathFrom(parent, goal, start){ const p=[]; let cur=goal; while(cur!==undefined){p.unshift(cur); if(cur===start)return p;cur=parent[cur];} return []; }

function pathFrames(id) {
  const g=state.grid || (state.grid=randomGrid()), frames=[], seen=new Set([g.start]), parent={}, visited=[]; let frontier=[g.start];
  const weighted=['dijkstra','astar','greedy-best'].includes(id), dist={[g.start]:0};
  const snap=(current,message,line,path=[])=>frames.push({kind:'grid',visited:[...visited],frontier:[...frontier],current,path,message,line});
  snap(g.start,'Start node added to the frontier.',0);
  while(frontier.length){
    let current;
    if(id==='bfs') current=frontier.shift(); else if(id==='dfs') current=frontier.pop(); else { frontier.sort((a,b)=>{ const score=x=>id==='dijkstra'?dist[x]:id==='astar'?dist[x]+heuristic(x,g.goal,g):heuristic(x,g.goal,g); return score(a)-score(b); }); current=frontier.shift(); }
    if(!visited.includes(current)) visited.push(current);
    snap(current, current===g.goal?'Goal reached. Reconstructing the path…':`Visit node ${current}.`, id==='bfs'||id==='dfs'?2:3);
    if(current===g.goal){ const path=pathFrom(parent,g.goal,g.start); path.forEach((_,i)=>snap(current,`Path found: ${path.length-1} steps${weighted&&id!=='greedy-best'?`, cost ${dist[g.goal]}`:''}.`,id==='dijkstra'?6:4,path.slice(0,i+1))); break; }
    neighbors(current,g).forEach(next=>{ const cost=(id==='dijkstra'||id==='astar')?g.weights[next]:1; const candidate=(dist[current]??0)+cost;if(!seen.has(next)||(weighted&&id!=='greedy-best'&&candidate<(dist[next]??Infinity))){seen.add(next);parent[next]=current;dist[next]=candidate;if(!frontier.includes(next))frontier.push(next);}});
    snap(current,`Frontier now holds ${frontier.length} candidate${frontier.length===1?'':'s'}.`,5);
  }
  if(!frames.at(-1)?.path?.length) snap(null,'No route reaches the goal.',4);
  return frames;
}

function baseValues(sorted=false){ if(!state.values.length) state.values=shuffle([12,19,25,31,38,44,50,57,63,69,75,82,88,94,101,108]); return sorted?[...state.values].sort((a,b)=>a-b):[...state.values]; }
function barFrame(frames,a,active=[],sorted=[],message='',line=0,rangeMark=null,pivot=null){frames.push({kind:'bars',array:[...a],active,sorted,message,line,range:rangeMark,pivot,target:state.target});}
function sortFrames(id){
  const a=baseValues(), f=[], n=a.length; barFrame(f,a,[],[], 'A fresh array is ready.',0);
  if(id==='bubble') for(let end=n-1;end>0;end--){let sw=false;for(let i=0;i<end;i++){barFrame(f,a,[i,i+1],range(end+1,n),`Compare ${a[i]} and ${a[i+1]}.`,2);if(a[i]>a[i+1]){[a[i],a[i+1]]=[a[i+1],a[i]];sw=true;barFrame(f,a,[i,i+1],range(end+1,n), 'Swap the pair.',4);}}if(!sw)break;}
  if(id==='selection') for(let left=0;left<n-1;left++){let min=left;for(let i=left+1;i<n;i++){barFrame(f,a,[min,i],range(left),`Smallest so far: ${a[min]}.`,2);if(a[i]<a[min])min=i;}[a[left],a[min]]=[a[min],a[left]];barFrame(f,a,[left,min],range(left+1),`Place ${a[left]} at position ${left+1}.`,4);}
  if(id==='insertion') for(let i=1;i<n;i++){let key=a[i],j=i-1;barFrame(f,a,[i],range(i),`Insert ${key} into the sorted prefix.`,1);while(j>=0&&a[j]>key){a[j+1]=a[j];barFrame(f,a,[j,j+1],range(i),`Shift ${a[j]} right.`,4);j--;}a[j+1]=key;barFrame(f,a,[j+1],range(i+1),`${key} is now in place.`,6);}
  if(id==='merge'){const merge=(l,r)=>{if(r-l<2)return;const m=Math.floor((l+r)/2);merge(l,m);merge(m,r);const left=a.slice(l,m),right=a.slice(m,r);let i=0,j=0,k=l;barFrame(f,a,range(l,r),[],`Merge ranges ${l+1}–${m} and ${m+1}–${r}.`,4,[l,r]);while(i<left.length||j<right.length){if(j>=right.length||(i<left.length&&left[i]<=right[j]))a[k++]=left[i++];else a[k++]=right[j++];barFrame(f,a,[k-1],[],`Copy the next smallest value.`,5,[l,r]);}};merge(0,n);}
  if(id==='quick'){const quick=(lo,hi)=>{if(lo>=hi)return;const pivot=a[hi];let p=lo;barFrame(f,a,[hi],[],`Pivot is ${pivot}.`,1,[lo,hi],hi);for(let i=lo;i<hi;i++){barFrame(f,a,[i,hi],[],`Compare ${a[i]} with pivot ${pivot}.`,5,[lo,hi],hi);if(a[i]<=pivot){[a[i],a[p]]=[a[p],a[i]];barFrame(f,a,[i,p],[],`Move ${a[p]} into the lower partition.`,5,[lo,hi],hi);p++;}}[a[p],a[hi]]=[a[hi],a[p]];barFrame(f,a,[p],[],`Pivot ${pivot} reaches its final position.`,5,[lo,hi],p);quick(lo,p-1);quick(p+1,hi);};quick(0,n-1);}
  if(id==='heap'){const sift=(size,root)=>{while(true){let largest=root,l=root*2+1,r=l+1;if(l<size&&a[l]>a[largest])largest=l;if(r<size&&a[r]>a[largest])largest=r;if(largest===root)break;barFrame(f,a,[root,largest],range(size,n),`Swap parent ${a[root]} with larger child ${a[largest]}.`,4);[a[root],a[largest]]=[a[largest],a[root]];root=largest;}};for(let i=Math.floor(n/2)-1;i>=0;i--)sift(n,i);barFrame(f,a,[0],[], 'Max-heap built.',0);for(let end=n-1;end>0;end--){[a[0],a[end]]=[a[end],a[0]];barFrame(f,a,[0,end],range(end,n),`Move maximum ${a[end]} to the end.`,2);sift(end,0);}}
  barFrame(f,a,[],range(n),'Sorted. Every value is in its final position.',0); return f;
}

function searchFrames(id){const a=baseValues(true),f=[];state.target=state.target??a[randomInt(3,a.length-4)];barFrame(f,a,[],[],`Find ${state.target}.`,0,[0,a.length-1]);if(id==='linear'){for(let i=0;i<a.length;i++){barFrame(f,a,[i],range(i),`Check ${a[i]} against ${state.target}.`,1,[i,a.length-1]);if(a[i]===state.target){barFrame(f,a,[i],[i],`Found ${state.target} at position ${i+1}.`,2);break;}}}else{let lo=0,hi=a.length-1;while(lo<=hi){let mid=Math.floor((lo+hi)/2);barFrame(f,a,[mid],[],`Middle value is ${a[mid]}.`,2,[lo,hi]);if(a[mid]===state.target){barFrame(f,a,[mid],[mid],`Found ${state.target} at position ${mid+1}.`,3,[mid,mid]);break;}if(a[mid]<state.target){lo=mid+1;barFrame(f,a,[],[],`${a[mid]} is too small. Discard the left half.`,4,[lo,hi]);}else{hi=mid-1;barFrame(f,a,[],[],`${a[mid]} is too large. Discard the right half.`,5,[lo,hi]);}}}return f;}

const graphData={nodes:[['A',13,48],['B',32,18],['C',55,35],['D',78,15],['E',85,65],['F',55,78],['G',26,78]],edges:[['A','B',4],['A','G',7],['A','C',9],['B','C',2],['B','D',8],['C','D',3],['C','E',6],['C','F',4],['C','G',5],['D','E',5],['E','F',1],['F','G',3]]};
function graphFrame(f,selected=[],active=null,visited=[],message='',line=0,order=[]){f.push({kind:'graph',selected:clone(selected),active,visited:[...visited],message,line,order});}
function graphFrames(id){
  const f=[],edges=graphData.edges.map((e,i)=>({u:e[0],v:e[1],w:e[2],i}));
  if(id==='prim'){let visited=new Set(['A']),selected=[];graphFrame(f,selected,null,[...visited],'Begin the tree at A.',0);while(visited.size<graphData.nodes.length){const choices=edges.filter(e=>(visited.has(e.u)&&!visited.has(e.v))||(visited.has(e.v)&&!visited.has(e.u))).sort((a,b)=>a.w-b.w);const e=choices[0],newNode=visited.has(e.u)?e.v:e.u;graphFrame(f,selected,e.i,[...visited],`Cheapest crossing edge is ${e.u}–${e.v} (${e.w}).`,2);selected.push(e.i);visited.add(newNode);graphFrame(f,selected,e.i,[...visited],`Add ${newNode} to the tree.`,3);}graphFrame(f,selected,null,[...visited],`Minimum spanning tree complete. Weight ${selected.reduce((s,i)=>s+edges[i].w,0)}.`,0);}
  if(id==='kruskal'){const parent=Object.fromEntries(graphData.nodes.map(n=>[n[0],n[0]])),find=x=>parent[x]===x?x:(parent[x]=find(parent[x])),selected=[];graphFrame(f,[],null,[],'Sort all edges by weight.',0);for(const e of [...edges].sort((a,b)=>a.w-b.w)){graphFrame(f,selected,e.i,[],`Consider ${e.u}–${e.v} (${e.w}).`,1);if(find(e.u)!==find(e.v)){parent[find(e.u)]=find(e.v);selected.push(e.i);graphFrame(f,selected,e.i,[], 'Accept: it connects two components.',3);}else graphFrame(f,selected,e.i,[], 'Skip: it would create a cycle.',2);if(selected.length===graphData.nodes.length-1)break;}graphFrame(f,selected,null,[],`Minimum spanning tree complete. Weight ${selected.reduce((s,i)=>s+edges[i].w,0)}.`,0);}
  if(id==='topological'){const directed=[['A','C'],['A','B'],['B','D'],['C','D'],['C','F'],['D','E'],['F','E'],['G','F']],indeg=Object.fromEntries(graphData.nodes.map(n=>[n[0],0]));directed.forEach(e=>indeg[e[1]]++);let q=Object.keys(indeg).filter(k=>!indeg[k]),order=[];f.push({kind:'graph',selected:[],active:null,visited:[],message:`Ready nodes: ${q.join(', ')}.`,line:0,order,directed});while(q.length){const node=q.shift();order.push(node);f.push({kind:'graph',selected:[],active:null,visited:[...order],message:`Emit ${node}; it has no remaining prerequisites.`,line:2,order:[...order],directed});directed.filter(e=>e[0]===node).forEach(e=>{indeg[e[1]]--;if(indeg[e[1]]===0)q.push(e[1]);});}f.push({kind:'graph',selected:[],active:null,visited:[...order],message:`Valid order: ${order.join(' → ')}.`,line:0,order,directed});}
  return f;
}

function dpFrames(id){const f=[];if(id==='knapsack'){const items=[['Map',2,3],['Rope',3,4],['Water',4,8],['Food',5,8],['Radio',6,9]],cap=10,table=Array.from({length:items.length+1},()=>Array(cap+1).fill(0));f.push({kind:'dp',table:clone(table),rows:['—',...items.map(x=>x[0])],cols:range(cap+1),current:null,message:'Each cell will store the best value for this capacity.',line:0,items});for(let i=1;i<=items.length;i++){const [name,w,v]=items[i-1];for(let c=0;c<=cap;c++){const skip=table[i-1][c];let take=-Infinity;if(w<=c)take=v+table[i-1][c-w];table[i][c]=Math.max(skip,take);f.push({kind:'dp',table:clone(table),rows:['—',...items.map(x=>x[0])],cols:range(cap+1),current:[i,c],source:w<=c?[[i-1,c],[i-1,c-w]]:[[i-1,c]],message:`${name}, capacity ${c}: ${take>skip?`take it → ${take}`:`skip it → ${skip}`}.`,line:w<=c?5:6,items});}}f.push({kind:'dp',table:clone(table),rows:['—',...items.map(x=>x[0])],cols:range(cap+1),current:[items.length,cap],message:`Best value at capacity ${cap}: ${table.at(-1).at(-1)}.`,line:0,items});}else{const x='ALGORITHM',y='LOGARITHM',table=Array.from({length:x.length+1},()=>Array(y.length+1).fill(0));f.push({kind:'dp',table:clone(table),rows:['∅',...x],cols:['∅',...y],current:null,message:`Compare “${x}” with “${y}”.`,line:0});for(let i=1;i<=x.length;i++)for(let j=1;j<=y.length;j++){const match=x[i-1]===y[j-1];table[i][j]=match?table[i-1][j-1]+1:Math.max(table[i-1][j],table[i][j-1]);f.push({kind:'dp',table:clone(table),rows:['∅',...x],cols:['∅',...y],current:[i,j],source:match?[[i-1,j-1]]:[[i-1,j],[i,j-1]],message:match?`${x[i-1]} matches. Extend the diagonal.`:`${x[i-1]} ≠ ${y[j-1]}. Keep the better prefix.`,line:match?3:5});}f.push({kind:'dp',table:clone(table),rows:['∅',...x],cols:['∅',...y],current:[x.length,y.length],message:`Longest common subsequence length: ${table.at(-1).at(-1)}.`,line:0});}return f;}

function greedyFrames(id){if(id==='activity'){const acts=[['A',0,3],['B',1,5],['C',4,7],['D',3,9],['E',5,9],['F',8,11],['G',9,12],['H',11,14]],sorted=[...acts].sort((a,b)=>a[2]-b[2]),f=[],selected=[];f.push({kind:'activity',acts,selected:[],current:null,message:'Activities are ordered by finish time.',line:0});let finish=-1;sorted.forEach(a=>{f.push({kind:'activity',acts,selected:[...selected],current:a[0],message:`Consider ${a[0]}: ${a[1]}–${a[2]}.`,line:3});if(a[1]>=finish){selected.push(a[0]);finish=a[2];f.push({kind:'activity',acts,selected:[...selected],current:a[0],message:`Select ${a[0]}; the schedule now ends at ${finish}.`,line:4});}else f.push({kind:'activity',acts,selected:[...selected],current:a[0],message:`Skip ${a[0]}; it overlaps the current schedule.`,line:3});});f.push({kind:'activity',acts,selected,current:null,message:`Maximum compatible set: ${selected.join(', ')}.`,line:0});return f;}const freq=[['A',5],['B',9],['C',12],['D',13],['E',16],['F',45]],heap=freq.map(([label,freq])=>({label,freq,id:label})),frames=[];let serial=0;frames.push({kind:'huffman',forest:clone(heap),active:[],message:'Start with one leaf per symbol.',line:0});while(heap.length>1){heap.sort((a,b)=>a.freq-b.freq);const left=heap.shift(),right=heap.shift();frames.push({kind:'huffman',forest:clone([...heap,left,right]),active:[left.id,right.id],message:`Merge the two smallest frequencies: ${left.freq} and ${right.freq}.`,line:2});const node={label:'',freq:left.freq+right.freq,id:`N${serial++}`,left,right};heap.push(node);frames.push({kind:'huffman',forest:clone(heap),active:[node.id],message:`Return their parent (${node.freq}) to the heap.`,line:5});}frames.push({kind:'huffman',forest:clone(heap),active:[],message:'One tree remains. Left edges are 0; right edges are 1.',line:0});return frames;}

function buildFrames(){const id=state.algorithm.id;if(state.algorithm.category==='Pathfinding')return pathFrames(id);if(state.algorithm.category==='Sorting')return sortFrames(id);if(state.algorithm.category==='Searching')return searchFrames(id);if(state.algorithm.category==='Graph')return graphFrames(id);if(state.algorithm.category==='Dynamic Programming')return dpFrames(id);return greedyFrames(id);}
function selectAlgorithm(id){stop();state.algorithm=byId[id];state.index=0;state.grid=state.algorithm.category==='Pathfinding'?randomGrid():null;state.values=[];state.target=null;state.frames=buildFrames();buildNav();updateLesson();render();document.body.classList.remove('menu-open');history.replaceState(null,'',`#${id}`);}
function escapeHtml(s){return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));}
function updateLesson(){const a=state.algorithm;$('#category-label').textContent=a.category;$('#algorithm-label').textContent=a.name;$('#eyebrow').textContent=`${a.category.toUpperCase()} · ${a.family.toUpperCase()}`;$('#algorithm-title').textContent=a.name;$('#algorithm-summary').textContent=a.summary;$('#time-complexity').textContent=a.time;$('#space-complexity').textContent=a.space;$('#explain-content').innerHTML=`<h3>How it thinks</h3><p>${a.summary}</p><ol>${a.steps.map(s=>`<li>${s}</li>`).join('')}</ol>`;$('#code-content code').innerHTML=a.code.map((line,i)=>`<span class="code-line" data-line="${i}">${escapeHtml(line)}</span>`).join('');$('#concept-strip').innerHTML=a.concepts.map(([tag,title,copy])=>`<article class="concept-card"><span>${tag}</span><strong>${title}</strong><p>${copy}</p></article>`).join('');updateLegend();}
function updateLegend(){const type=state.algorithm.category;let html='',hint='';if(type==='Pathfinding'){html='<span><i style="background:var(--green)"></i>Start</span><span><i style="background:var(--coral)"></i>Goal</span><span><i style="background:#334b60"></i>Wall</span><span><i style="background:var(--cyan-strong)"></i>Visited</span><span><i style="background:var(--amber)"></i>Path</span>';hint='Click cells to draw walls';}else if(type==='Sorting'||type==='Searching'){html='<span><i style="background:var(--cyan-strong)"></i>Value</span><span><i style="background:var(--amber)"></i>Comparing</span><span><i style="background:var(--green)"></i>Final</span>';hint=type==='Searching'?`Target: ${state.target??'—'}`:'Bar height = value';}else if(type==='Graph'){html='<span><i style="background:var(--cyan-strong)"></i>Selected</span><span><i style="background:var(--amber)"></i>Considering</span>';hint='Edge labels show weight';}else if(type==='Dynamic Programming'){html='<span><i style="background:var(--cyan-strong)"></i>Current state</span><span><i style="background:var(--violet)"></i>Reused state</span>';hint='Rows and columns define each subproblem';}else{html='<span><i style="background:var(--green)"></i>Selected</span><span><i style="background:var(--amber)"></i>Considering</span>';hint='Greedy choice at each step';}$('#legend').innerHTML=html;$('#interaction-hint').textContent=hint;}

function render(){if(!state.frames.length)return;const frame=state.frames[state.index],stage=$('#visual-stage');stage.className=`visual-stage ${frame.kind}-stage`;if(frame.kind==='grid')renderGrid(stage,frame);if(frame.kind==='bars')renderBars(stage,frame);if(frame.kind==='graph')renderGraph(stage,frame);if(frame.kind==='dp')renderDP(stage,frame);if(frame.kind==='activity')renderActivity(stage,frame);if(frame.kind==='huffman')renderHuffman(stage,frame);$('#step-bubble').textContent=`${String(state.index+1).padStart(2,'0')} / ${String(state.frames.length).padStart(2,'0')} — ${frame.message}`;$('#now-copy').textContent=frame.message;const pct=state.frames.length<2?100:(state.index/(state.frames.length-1))*100;$('#progress-fill').style.width=`${pct}%`;$('#progress-track').setAttribute('aria-valuenow',Math.round(pct));$$('.code-line').forEach((line,i)=>line.classList.toggle('active',i===frame.line));$('#back-button').disabled=state.index===0;$('#next-button').disabled=state.index===state.frames.length-1;$('#play-button b').textContent=state.playing?'Pause':state.index===state.frames.length-1?'Replay':'Run';$('#play-button span').textContent=state.playing?'Ⅱ':'▶';}
function renderGrid(stage,frame){const g=state.grid;stage.innerHTML=`<div class="grid-board" style="--cols:${g.cols}"></div>`;const board=stage.firstElementChild,visited=new Set(frame.visited),frontier=new Set(frame.frontier),path=new Set(frame.path||[]);for(let i=0;i<g.rows*g.cols;i++){const c=document.createElement('button');c.className='grid-cell';c.dataset.index=i;c.setAttribute('aria-label',`Grid cell ${Math.floor(i/g.cols)+1}, ${i%g.cols+1}`);if(g.walls.includes(i))c.classList.add('wall');if(visited.has(i))c.classList.add('visited');if(frontier.has(i))c.classList.add('frontier');if(path.has(i))c.classList.add('path');if(i===frame.current)c.classList.add('current');if(i===g.start)c.classList.add('start');if(i===g.goal)c.classList.add('goal');if(state.algorithm.family==='weighted'&&!g.walls.includes(i)&&i!==g.start&&i!==g.goal)c.innerHTML=`<small>${g.weights[i]}</small>`;board.appendChild(c);}}
function renderBars(stage,frame){const max=Math.max(...frame.array),sorted=new Set(frame.sorted),active=new Set(frame.active);stage.innerHTML=`<div class="bars" role="img" aria-label="Array values ${frame.array.join(', ')}">${frame.array.map((v,i)=>`<div class="bar-slot ${frame.range&&(i<frame.range[0]||i>frame.range[1])?'muted':''}"><span class="bar ${sorted.has(i)?'sorted':''} ${active.has(i)?'active':''} ${frame.pivot===i?'pivot':''}" style="height:${Math.max(13,v/max*100)}%"></span><b>${v}</b><em>${i+1}</em></div>`).join('')}</div>${frame.target!=null?`<div class="target-chip">TARGET <strong>${frame.target}</strong></div>`:''}`;}
function renderGraph(stage,frame){const nodeMap=Object.fromEntries(graphData.nodes.map(n=>[n[0],n])),edges=frame.directed?frame.directed.map((e,i)=>[e[0],e[1],'',i]):graphData.edges,selected=new Set(frame.selected||[]),visited=new Set(frame.visited||[]);stage.innerHTML=`<div class="graph-wrap"><svg viewBox="0 0 100 92" role="img" aria-label="Graph visualization"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#52677b"/></marker></defs>${edges.map((e,i)=>{const a=nodeMap[e[0]],b=nodeMap[e[1]],on=selected.has(i),active=frame.active===i;return `<g class="edge ${on?'selected':''} ${active?'active':''}"><line x1="${a[1]}" y1="${a[2]}" x2="${b[1]}" y2="${b[2]}" ${frame.directed?'marker-end="url(#arrow)"':''}/>${e[2]!==''?`<text x="${(a[1]+b[1])/2}" y="${(a[2]+b[2])/2-1}">${e[2]}</text>`:''}</g>`}).join('')}${graphData.nodes.map(n=>`<g class="graph-node ${visited.has(n[0])?'visited':''}"><circle cx="${n[1]}" cy="${n[2]}" r="5"/><text x="${n[1]}" y="${n[2]+1.5}">${n[0]}</text></g>`).join('')}</svg>${frame.order?.length?`<div class="order-row">${frame.order.map((n,i)=>`<span>${n}</span>${i<frame.order.length-1?'<b>→</b>':''}`).join('')}</div>`:''}</div>`;}
function renderDP(stage,frame){stage.innerHTML=`<div class="dp-shell">${frame.items?`<div class="item-chips">${frame.items.map(x=>`<span><b>${x[0]}</b> w${x[1]} · v${x[2]}</span>`).join('')}</div>`:''}<div class="dp-table" style="grid-template-columns:minmax(60px,1.3fr) repeat(${frame.cols.length},minmax(34px,1fr))"><div class="dp-cell head corner"></div>${frame.cols.map(c=>`<div class="dp-cell head">${c}</div>`).join('')}${frame.table.map((row,i)=>`<div class="dp-cell head">${frame.rows[i]}</div>${row.map((v,j)=>`<div class="dp-cell ${frame.current&&frame.current[0]===i&&frame.current[1]===j?'current':''} ${(frame.source||[]).some(x=>x[0]===i&&x[1]===j)?'source':''}">${v}</div>`).join('')}`).join('')}</div></div>`;}
function renderActivity(stage,frame){const selected=new Set(frame.selected);stage.innerHTML=`<div class="timeline"><div class="time-axis">${range(15).map(i=>`<span style="left:${i/14*100}%">${i}</span>`).join('')}</div>${frame.acts.map(a=>`<div class="activity-row"><b>${a[0]}</b><span class="activity ${selected.has(a[0])?'selected':''} ${frame.current===a[0]?'active':''}" style="left:${a[1]/14*100}%;width:${(a[2]-a[1])/14*100}%">${a[1]}–${a[2]}</span></div>`).join('')}</div>`;}
function flattenTree(node,depth=0,x=50,spread=25,out={nodes:[],edges:[]}){out.nodes.push({id:node.id,label:node.label,freq:node.freq,x,y:10+depth*22});if(node.left){out.edges.push([node.id,node.left.id,'0']);flattenTree(node.left,depth+1,x-spread,spread/2,out);}if(node.right){out.edges.push([node.id,node.right.id,'1']);flattenTree(node.right,depth+1,x+spread,spread/2,out);}return out;}
function renderHuffman(stage,frame){const active=new Set(frame.active);if(frame.forest.length===1&&frame.forest[0].left){const t=flattenTree(frame.forest[0]),map=Object.fromEntries(t.nodes.map(n=>[n.id,n]));stage.innerHTML=`<div class="huffman-tree"><svg viewBox="0 0 100 125">${t.edges.map(e=>`<g><line x1="${map[e[0]].x}" y1="${map[e[0]].y}" x2="${map[e[1]].x}" y2="${map[e[1]].y}"/><text x="${(map[e[0]].x+map[e[1]].x)/2}" y="${(map[e[0]].y+map[e[1]].y)/2}">${e[2]}</text></g>`).join('')}${t.nodes.map(n=>`<g class="huff-node"><circle cx="${n.x}" cy="${n.y}" r="5"/><text x="${n.x}" y="${n.y+1.4}">${n.label||n.freq}</text></g>`).join('')}</svg></div>`;}else stage.innerHTML=`<div class="frequency-board">${frame.forest.sort((a,b)=>a.freq-b.freq).map(n=>`<div class="frequency-card ${active.has(n.id)?'active':''}"><span>${n.label||'node'}</span><strong>${n.freq}</strong><small>frequency</small></div>`).join('')}</div>`;}

function step(delta){stop();state.index=clamp(state.index+delta,0,state.frames.length-1);render();}
function play(){if(state.playing){stop();render();return;}if(state.index>=state.frames.length-1)state.index=0;state.playing=true;render();tick();}
function tick(){clearTimeout(state.timer);if(!state.playing)return;if(state.index>=state.frames.length-1){stop();render();return;}state.timer=setTimeout(()=>{state.index++;render();tick();},state.speed);}
function stop(){state.playing=false;clearTimeout(state.timer);state.timer=null;}
function randomize(){stop();state.grid=state.algorithm.category==='Pathfinding'?randomGrid():null;state.values=[];state.target=null;state.index=0;state.frames=buildFrames();updateLegend();render();}

function bindUI(){$('#play-button').addEventListener('click',play);$('#next-button').addEventListener('click',()=>step(1));$('#back-button').addEventListener('click',()=>step(-1));$('#restart-button').addEventListener('click',()=>{stop();state.index=0;render();});$('#randomize-button').addEventListener('click',randomize);$('#speed-select').addEventListener('change',e=>{state.speed=Number(e.target.value);if(state.playing)tick();});$('#progress-track').addEventListener('click',e=>{stop();const r=e.currentTarget.getBoundingClientRect();state.index=Math.round(clamp((e.clientX-r.left)/r.width,0,1)*(state.frames.length-1));render();});$('#visual-stage').addEventListener('click',e=>{const cell=e.target.closest('.grid-cell');if(!cell||state.algorithm.category!=='Pathfinding')return;const i=Number(cell.dataset.index),g=state.grid;if(i===g.start||i===g.goal)return;stop();g.walls=g.walls.includes(i)?g.walls.filter(x=>x!==i):[...g.walls,i];state.frames=buildFrames();state.index=0;render();});$$('.explain-tabs button').forEach(button=>button.addEventListener('click',()=>{$$('.explain-tabs button').forEach(item=>item.classList.toggle('active',item===button));$('#explain-content').classList.toggle('hidden',button.dataset.tab!=='explain');$('#code-content').classList.toggle('hidden',button.dataset.tab!=='code');}));$('#menu-button').addEventListener('click',()=>document.body.classList.toggle('menu-open'));$('#help-button').addEventListener('click',()=>$('#shortcut-modal').classList.remove('hidden'));$('#close-help').addEventListener('click',()=>$('#shortcut-modal').classList.add('hidden'));$('#shortcut-modal').addEventListener('click',e=>{if(e.target.id==='shortcut-modal')e.currentTarget.classList.add('hidden');});document.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();play();}if(e.key==='ArrowRight')step(1);if(e.key==='ArrowLeft')step(-1);if(e.key.toLowerCase()==='r')randomize();if(e.key==='Escape'){$('#shortcut-modal').classList.add('hidden');document.body.classList.remove('menu-open');}});}
function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;const register=tool=>Promise.resolve(context.registerTool(tool)).catch(()=>{});register({name:'select_algorithm',title:'Select algorithm',description:'Open one of the 20 algorithm visualizations by its stable id.',inputSchema:{type:'object',properties:{id:{type:'string',enum:algorithms.map(a=>a.id)}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute({id}){if(!byId[id])throw new Error('Unknown algorithm id');selectAlgorithm(id);return {algorithm:state.algorithm.name,steps:state.frames.length};}});register({name:'step_visualization',title:'Step visualization',description:'Move the current visualization forward or backward by a number of steps.',inputSchema:{type:'object',properties:{delta:{type:'integer',minimum:-100,maximum:100}},required:['delta'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute({delta}){step(delta);return {algorithm:state.algorithm.name,step:state.index+1,total:state.frames.length,explanation:state.frames[state.index].message};}});register({name:'read_visualization',title:'Read visualization state',description:'Read the selected algorithm and current visible step without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return {id:state.algorithm.id,algorithm:state.algorithm.name,step:state.index+1,total:state.frames.length,explanation:state.frames[state.index].message};}});}

const requested=location.hash.slice(1);if(byId[requested])state.algorithm=byId[requested];state.grid=state.algorithm.category==='Pathfinding'?randomGrid():null;state.frames=buildFrames();buildNav();updateLesson();bindUI();render();registerWebMCP();
